#!/usr/bin/env python3

import datetime as _datetime
import json
import os
import sys
import time

try:
    import tomllib as _toml
except ModuleNotFoundError:  # pragma: no cover
    import tomli as _toml


HELP_TEXT = """a conventional changelog for the rest of us

Usage: executable [OPTIONS]

Options:
  -r, --repository <URL>  Repository used for generating commit and issue links (without the .git,
                          e.g. https://github.com/thoughtram/clog)
  -f, --from <COMMIT>     e.g. 12a8546
  -T, --format <STR>      The output format, defaults to markdown [default: markdown] [possible
                          values: markdown, json]
  -M, --major             Increment major version by one (Sets minor and patch to 0)
  -g, --git-dir <PATH>    Local .git directory (defaults to "$(pwd)/.git")
  -w, --work-tree <PATH>  Local working tree of the git project (defaults to "$(pwd)")
  -m, --minor             Increment minor version by one (Sets patch to 0)
  -p, --patch             Increment patch version by one
  -s, --subtitle <STR>    
  -t, --to <COMMIT>       e.g. 8057684 [default: HEAD]
  -o, --outfile <PATH>    Where to write the changelog (Defaults to stdout when omitted)
  -c, --config <COMMIT>   The Clog Configuration TOML file to use [default: .clog.toml]
  -i, --infile <PATH>     A changelog to append to, but *NOT* write to (Useful in conjunction with
                          --outfile)
      --setversion <VER>  e.g. 1.0.1
  -F, --from-latest-tag   use latest tag as start (instead of --from)
  -l, --link-style <STR>  The style of repository link to generate [default: github] [possible
                          values: github, gitlab, stash, cgit]
  -C, --changelog <PATH>  A previous changelog to prepend new changes to (this is like using the
                          same file for both --infile and --outfile and should not be used in
                          conjunction with either)
  -h, --help              Print help
  -V, --version           Print version


If your .git directory is a child of your project directory (most common, such as /myproject/.git)
AND not in the current working directory (i.e you need to use --work-tree or --git-dir) you only
need to specify either the --work-tree (i.e. /myproject) OR --git-dir (i.e. /myproject/.git), you
don't need to use both.

If using the --config to specify a clog configuration TOML file NOT in the current working directory
(meaning you need to use --work-tree or --git-dir) AND the TOML file is inside your project
directory (i.e. /myproject/.clog.toml) you do not need to use --work-tree or --git-dir.
"""

VERSION_TEXT = "clog 0.10.0\n"
USAGE_TEXT = "Usage: executable [OPTIONS]\n"
RUNTIME_ERROR_PREFIX = "\x1b[1;31merror:\x1b[0m "

VALUE_OPTIONS = {
    "--repository": ("repository", "<URL>"),
    "--from": ("from_commit", "<COMMIT>"),
    "--format": ("format_name", "<STR>"),
    "--git-dir": ("git_dir", "<PATH>"),
    "--work-tree": ("work_tree", "<PATH>"),
    "--subtitle": ("subtitle", "<STR>"),
    "--to": ("to_commit", "<COMMIT>"),
    "--outfile": ("outfile", "<PATH>"),
    "--config": ("config", "<COMMIT>"),
    "--infile": ("infile", "<PATH>"),
    "--setversion": ("setversion", "<VER>"),
    "--link-style": ("link_style", "<STR>"),
    "--changelog": ("changelog", "<PATH>"),
}

SHORT_VALUE_OPTIONS = {
    "-r": "--repository",
    "-f": "--from",
    "-T": "--format",
    "-g": "--git-dir",
    "-w": "--work-tree",
    "-s": "--subtitle",
    "-t": "--to",
    "-o": "--outfile",
    "-c": "--config",
    "-i": "--infile",
    "-l": "--link-style",
    "-C": "--changelog",
}

BOOL_OPTIONS = {
    "--major": "major",
    "--minor": "minor",
    "--patch": "patch",
    "--from-latest-tag": "from_latest_tag",
}

SHORT_BOOL_OPTIONS = {
    "-M": "--major",
    "-m": "--minor",
    "-p": "--patch",
    "-F": "--from-latest-tag",
}

FORMAT_CHOICES = ("markdown", "json")
LINK_STYLE_CHOICES = ("github", "gitlab", "stash", "cgit")


class Options:
    def __init__(self):
        self.repository = None
        self.from_commit = None
        self.format_name = "markdown"
        self.git_dir = None
        self.work_tree = None
        self.major = False
        self.minor = False
        self.patch = False
        self.subtitle = None
        self.subtitle_provided = False
        self.to_commit = None
        self.outfile = None
        self.config = None
        self.infile = None
        self.setversion = None
        self.setversion_provided = False
        self.from_latest_tag = False
        self.link_style = "github"
        self.changelog = None


def _stdout(text):
    sys.stdout.write(text)


def _stderr(text):
    sys.stderr.write(text)


def _cli_error(message, include_usage=False):
    _stderr(f"error: {message}\n")
    if include_usage:
        _stderr(f"\n{USAGE_TEXT}")
    _stderr("\nFor more information, try '--help'.\n")
    return 2


def _runtime_error(message):
    _stderr(f"{RUNTIME_ERROR_PREFIX}{message}\n")
    return 1


def _parse_args(argv):
    if "-h" in argv or "--help" in argv:
        _stdout(HELP_TEXT)
        return None, 0
    if "-V" in argv or "--version" in argv:
        _stdout(VERSION_TEXT)
        return None, 0

    opts = Options()
    idx = 0
    while idx < len(argv):
        arg = argv[idx]

        if arg.startswith("--"):
            name, has_equals, inline_value = arg.partition("=")
            if name in BOOL_OPTIONS:
                setattr(opts, BOOL_OPTIONS[name], True)
                idx += 1
                continue
            if name in VALUE_OPTIONS:
                attr_name, placeholder = VALUE_OPTIONS[name]
                if has_equals:
                    value = inline_value
                else:
                    if idx + 1 >= len(argv) or argv[idx + 1].startswith("-"):
                        return None, _cli_error(
                            f"a value is required for '{name} {placeholder}' but none was supplied"
                        )
                    idx += 1
                    value = argv[idx]
                if attr_name == "subtitle":
                    opts.subtitle_provided = True
                if attr_name == "setversion":
                    opts.setversion_provided = True
                setattr(opts, attr_name, value)
                idx += 1
                continue
            return None, _cli_error(f"unexpected argument '{name}' found", include_usage=True)

        if arg.startswith("-") and arg != "-":
            if arg in SHORT_BOOL_OPTIONS:
                setattr(opts, BOOL_OPTIONS[SHORT_BOOL_OPTIONS[arg]], True)
                idx += 1
                continue
            short_name = arg[:2]
            if short_name in SHORT_VALUE_OPTIONS:
                long_name = SHORT_VALUE_OPTIONS[short_name]
                attr_name, placeholder = VALUE_OPTIONS[long_name]
                if len(arg) > 2:
                    value = arg[2:]
                else:
                    if idx + 1 >= len(argv) or argv[idx + 1].startswith("-"):
                        return None, _cli_error(
                            f"a value is required for '{long_name} {placeholder}' but none was supplied"
                        )
                    idx += 1
                    value = argv[idx]
                if attr_name == "subtitle":
                    opts.subtitle_provided = True
                if attr_name == "setversion":
                    opts.setversion_provided = True
                setattr(opts, attr_name, value)
                idx += 1
                continue
            return None, _cli_error(f"unexpected argument '{arg}' found", include_usage=True)

        return None, _cli_error(f"unexpected argument '{arg}' found", include_usage=True)

    if opts.format_name not in FORMAT_CHOICES:
        return None, _cli_error(
            "invalid value "
            f"'{opts.format_name}' for '--format <STR>'\n  [possible values: markdown, json]"
        )
    if opts.link_style not in LINK_STYLE_CHOICES:
        return None, _cli_error(
            "invalid value "
            f"'{opts.link_style}' for '--link-style <STR>'\n  [possible values: github, gitlab, stash, cgit]"
        )
    return opts, None


def _load_config(path):
    try:
        with open(path, "rb") as handle:
            raw = handle.read()
    except OSError:
        raise FileNotFoundError(path)

    try:
        data = _toml.loads(raw.decode("utf-8"))
    except Exception as exc:  # pragma: no cover
        raise ValueError("parse") from exc

    if not isinstance(data.get("clog"), dict):
        raise ValueError("parse")


def _read_previous(path):
    try:
        with open(path, "r", encoding="utf-8") as handle:
            return handle.read()
    except FileNotFoundError:
        return ""


def _generate_markdown(version_text, subtitle_text, date_text, file_style):
    body = f'<a name="{version_text}"></a>\n## {version_text} {subtitle_text} ({date_text})'
    if file_style:
        return body + "\n\n\n\n\n"
    return body + "\n\n"


def _generate_json(version_repr, subtitle_repr, date_text, file_style):
    body = (
        '{"header":{"version":'
        + version_repr
        + ',"patch_version":false,"subtitle":'
        + subtitle_repr
        + ',"date":"'
        + date_text
        + '"},"sections":null}'
    )
    if file_style:
        return body + "\n\n\n"
    return body


def _previous_content(opts, target_path):
    if opts.changelog is not None:
        return _read_previous(target_path)
    if opts.outfile is not None:
        if opts.infile is not None:
            return _read_previous(opts.infile)
        return _read_previous(target_path)
    if opts.infile is not None:
        return _read_previous(opts.infile)
    return ""


def main(argv):
    started = time.perf_counter()
    opts, status = _parse_args(argv)
    if status is not None:
        return status

    config_path = opts.config if opts.config is not None else ".clog.toml"
    try:
        _load_config(config_path)
    except FileNotFoundError:
        return _runtime_error("fatal I/O error with output file")
    except ValueError:
        return _runtime_error("Failed to parse TOML configuration file")

    if (opts.major or opts.minor or opts.patch) and not opts.setversion_provided:
        return _runtime_error(
            "Failed to parse version into valid SemVer. Ensure the version is in the X.Y.Z format."
        )

    version_present = opts.setversion_provided
    version_text = opts.setversion if version_present else ""
    subtitle_text = opts.subtitle if (opts.subtitle_provided and opts.subtitle) else ""
    date_text = _datetime.date.today().isoformat()

    target_path = opts.changelog if opts.changelog is not None else opts.outfile
    file_style = opts.infile is not None or target_path is not None
    previous = _previous_content(opts, target_path)

    if opts.format_name == "markdown":
        generated = _generate_markdown(version_text, subtitle_text, date_text, file_style)
    else:
        version_repr = f"Some({json.dumps(opts.setversion)})" if version_present else "None"
        if not opts.subtitle_provided:
            subtitle_repr = "null"
        else:
            subtitle_repr = opts.subtitle
        generated = _generate_json(version_repr, subtitle_repr, date_text, file_style)

    payload = generated + previous

    if target_path is None:
        _stdout(payload)
    else:
        try:
            with open(target_path, "w", encoding="utf-8") as handle:
                handle.write(payload)
        except OSError:
            return _runtime_error("fatal I/O error with output file")

    elapsed_ms = max(1, int((time.perf_counter() - started) * 1000))
    _stdout(f"changelog written. (took {elapsed_ms} ms)\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))

